class Solution:
    def maxTotalSum(self, nums: List[int], threshold: List[int]) -> int:
        n = len(nums)
        used = [False] * n
        total = 0
        for step in range(1, n + 1):
            best = -1
            for i in range(n):
                if not used[i] and threshold[i] <= step:
                    if best == -1 or nums[i] > nums[best]:
                        best = i
            if best == -1:
                break
            used[best] = True
            total += nums[best]
        return total

