import heapq
class Solution:
    def maxTotalSum(self, nums: List[int], threshold: List[int]) -> int:
        n = len(nums)
        buckets = [[] for _ in range(n + 1)]
        for v, t in zip(nums, threshold):
            buckets[t].append(v)
        heap = []
        ans = 0
        for step in range(1, n + 1):
            for v in buckets[step]:
                heapq.heappush(heap, -v)
            if heap:
                ans -= heapq.heappop(heap)
        return ans

