public:
    long long maxTotalSum(vector<int>& nums, vector<int>& threshold) {
        int n = nums.size();
        vector<vector<int>> buckets(n + 1);
        for (int i = 0; i < n; ++i) buckets[threshold[i]].push_back(nums[i]);
        priority_queue<int> pq;
        long long ans = 0;
        for (int step = 1; step <= n; ++step) {
            for (int v : buckets[step]) pq.push(v);
            if (!pq.empty()) { ans += pq.top(); pq.pop(); }
        }
        return ans;
    }
};

