var maxTotalSum = function(nums, threshold) {
    const n = nums.length;
    const buckets = Array.from({length: n + 1}, () => []);
    for (let i = 0; i < n; i++) buckets[threshold[i]].push(nums[i]);
    const heap = [];
    const push = v => { heap.push(v); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const top = heap[0], last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            for (;;) { let l = 2*i+1, r = l+1, m = i;
                if (l < heap.length && heap[l] > heap[m]) m = l;
                if (r < heap.length && heap[r] > heap[m]) m = r;
                if (m === i) break;
                [heap[m], heap[i]] = [heap[i], heap[m]]; i = m; } }
        return top; };
    let ans = 0;
    for (let step = 1; step <= n; step++) {
        for (const v of buckets[step]) push(v);
        if (heap.length) ans += pop();
    }
    return ans;
};
